package dev.genericpayments.platform.payments.adapter.out.persistence;
import dev.genericpayments.platform.payments.application.model.AdminPaymentViews.*;
import dev.genericpayments.platform.payments.application.port.out.AdminPaymentReadPort;
import java.sql.*;
import java.time.Instant;
import java.util.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;
import org.springframework.transaction.annotation.Transactional;
@Repository
@Transactional(readOnly=true)
public class AdminPaymentReadAdapter implements AdminPaymentReadPort {
    private final JdbcTemplate jdbc;
    public AdminPaymentReadAdapter(JdbcTemplate jdbc){this.jdbc=jdbc;}
    private static final String COLUMNS="p.id,p.site_id,p.payment_account_id,p.source,p.price_id,p.snapshot_price_key,p.snapshot_version,p.external_order_id,p.amount_minor,p.currency,p.tax_mode,p.tax_amount_minor,p.status,a.provider,p.refunded_amount_minor,p.created_at,p.updated_at,p.customer_id,p.donation_id,p.donation_campaign_id,p.snapshot_campaign_key,p.snapshot_campaign_version,p.subscription_id,p.billing_record_id,p.subscription_billing_kind,p.subscription_period_start,p.subscription_period_end,(case when p.status in ('SUCCEEDED','PARTIALLY_REFUNDED') then p.amount_minor-coalesce((select sum(r.amount_minor) from refunds r where r.payment_id=p.id and r.status in ('PENDING','PROCESSING','UNKNOWN','SUCCEEDED')),0) else 0 end) as available";
    private Projection projection(ResultSet r,int n)throws SQLException{return new Projection(uuid(r,"id"),uuid(r,"site_id"),uuid(r,"payment_account_id"),r.getString("source"),uuid(r,"price_id"),r.getString("snapshot_price_key"),r.getObject("snapshot_version",Integer.class),r.getString("external_order_id"),r.getLong("amount_minor"),r.getString("currency"),r.getString("tax_mode"),r.getObject("tax_amount_minor",Long.class),r.getString("status"),r.getString("provider"),r.getLong("available"),r.getLong("refunded_amount_minor"),time(r,"created_at"),time(r,"updated_at"),uuid(r,"customer_id"),uuid(r,"donation_id"),uuid(r,"donation_campaign_id"),r.getString("snapshot_campaign_key"),r.getObject("snapshot_campaign_version",Long.class),uuid(r,"subscription_id"),uuid(r,"billing_record_id"),r.getString("subscription_billing_kind")==null?null:dev.genericpayments.platform.payments.domain.SubscriptionBillingContext.Kind.valueOf(r.getString("subscription_billing_kind")),time(r,"subscription_period_start"),time(r,"subscription_period_end"));}
    public Page list(Query q){var where=new StringBuilder(" where 1=1");var args=new ArrayList<Object>();filter(where,args,"p.site_id",q.siteId());filter(where,args,"p.customer_id",q.customerId());filter(where,args,"p.donation_campaign_id",q.campaignId());filter(where,args,"p.donation_id",q.donationId());filter(where,args,"p.status",q.status()==null?null:q.status().name());filter(where,args,"p.external_order_id",q.externalOrderId());filter(where,args,"p.id",q.paymentId());filter(where,args,"a.provider",q.provider()==null?null:q.provider().name());if(q.createdFrom()!=null){where.append(" and p.created_at>=?");args.add(Timestamp.from(q.createdFrom()));}if(q.createdTo()!=null){where.append(" and p.created_at<?");args.add(Timestamp.from(q.createdTo()));}String from=" from payments p join payment_accounts a on a.id=p.payment_account_id";long total=jdbc.queryForObject("select count(*)"+from+where,Long.class,args.toArray());args.add(q.size());args.add((long)q.page()*q.size());String direction=q.sort()==Sort.CREATED_DESC?" desc":" asc";return new Page(jdbc.query("select "+COLUMNS+from+where+" order by p.created_at"+direction+",p.id"+direction+" limit ? offset ?",this::projection,args.toArray()),total,q.page(),q.size(),q.sort());}
    public Optional<Details> details(UUID id){var rows=jdbc.query("select "+COLUMNS+" from payments p join payment_accounts a on a.id=p.payment_account_id where p.id=?",this::projection,id);if(rows.size()!=1)return Optional.empty();var p=rows.getFirst();var site=p.siteId();
        var attempts=jdbc.query("select c.id,c.attempt_number,c.status,c.provider_intent_reference,c.payment_method_family,c.result_code,c.created_at,c.updated_at from payment_attempts c join payments p on p.id=c.payment_id where p.id=? and p.site_id=? order by c.attempt_number,c.id",(r,n)->new Attempt(uuid(r,"id"),r.getInt("attempt_number"),r.getString("status"),r.getString("provider_intent_reference"),r.getString("payment_method_family"),r.getString("result_code"),time(r,"created_at"),time(r,"updated_at")),id,site);
        var events=jdbc.query("select c.id,c.sequence_number,c.event_type,c.source,c.amount_minor,c.currency,c.provider_event_id,c.provider_object_id,c.request_id,c.occurred_at,c.received_at from payment_events c join payments p on p.id=c.payment_id and p.site_id=c.site_id where p.id=? and p.site_id=? order by c.sequence_number",(r,n)->new Event(uuid(r,"id"),r.getLong("sequence_number"),r.getString("event_type"),r.getString("source"),r.getObject("amount_minor",Long.class),r.getString("currency"),r.getString("provider_event_id"),r.getString("provider_object_id"),r.getString("request_id"),time(r,"occurred_at"),time(r,"received_at")),id,site);
        var refunds=jdbc.query("select c.id,c.amount_minor,c.currency,c.status,c.provider_refund_reference,c.reason_code,c.created_at,c.updated_at from refunds c join payments p on p.id=c.payment_id where p.id=? and p.site_id=? order by c.created_at,c.id",(r,n)->new RefundView(uuid(r,"id"),r.getLong("amount_minor"),r.getString("currency"),r.getString("status"),r.getString("provider_refund_reference"),r.getString("reason_code"),time(r,"created_at"),time(r,"updated_at")),id,site);
        var outbox=jdbc.query("select c.id,c.callback_type,c.status,c.attempt_count,c.next_attempt_at,c.created_at,c.updated_at from outbox_events c join payments p on p.id=c.payment_id and p.site_id=c.site_id where p.id=? and p.site_id=? order by c.created_at,c.id",(r,n)->new Outbox(uuid(r,"id"),r.getString("callback_type"),r.getString("status"),r.getInt("attempt_count"),time(r,"next_attempt_at"),time(r,"created_at"),time(r,"updated_at")),id,site);
        var deliveries=jdbc.query("select d.id,d.outbox_event_id,d.attempt_number,d.delivery_mode,d.status,d.http_status,d.error_category,d.started_at,d.finished_at from outbox_deliveries d join outbox_events c on c.id=d.outbox_event_id join payments p on p.id=c.payment_id and p.site_id=c.site_id where p.id=? and p.site_id=? order by d.attempt_number,d.id",(r,n)->new Delivery(uuid(r,"id"),uuid(r,"outbox_event_id"),r.getInt("attempt_number"),r.getString("delivery_mode"),r.getString("status"),r.getObject("http_status",Integer.class),r.getString("error_category"),time(r,"started_at"),time(r,"finished_at")),id,site);
        return Optional.of(new Details(p,attempts,events,refunds,outbox,deliveries));
    }
    private static void filter(StringBuilder sql,List<Object> args,String field,Object value){if(value!=null){sql.append(" and ").append(field).append("=?");args.add(value);}}
    private static UUID uuid(ResultSet r,String name)throws SQLException{return r.getObject(name,UUID.class);}
    private static Instant time(ResultSet r,String name)throws SQLException{var t=r.getTimestamp(name);return t==null?null:t.toInstant();}
}
